  "about.founderHeading": "📖 Про засновницю",
  "about.founder.p1": "Привіт! Я — Консепсьйон, засновниця Luminous StockHaven.",
  "about.founder.p2": "Я не з великої технологічної компанії і не сиджу в корпоративному офісі. Я — невелика власниця роздрібного магазину, така сама, як ви. Я керую п’ятьма інтернет-магазинами, що спеціалізуються на книгах і виготовлених вручну аксесуарах для любителів книг.\nЯк і багато незалежних продавців, я дійшла до межі, намагаючись керувати запасами в кількох місцях, відстежувати ISBN видавництв поряд із власними артикулами ручної роботи та обробляти замовлення постачальникам у громіздких таблицях. Коли я шукала застосунок, який мені допоможе, я спробувала шість різних варіантів. Кожен виявився або цілком неповним, або неймовірно заплутаним, або хижацьким — вони брали сотні доларів на місяць за базові інструменти.",
  "about.founder.p3": "Розчарувавшись у галузі, яка вичавлює незалежних творців, я вирішила створити власне рішення. Я збудувала Luminous StockHaven із необхідності — щоб вести свій бізнес чисто, ефективно та зі спокійною душею.",
  "about.founder.p4": "Я вирішила відкрити цю платформу для публіки за чесною, доступною ціною, бо кожен невеликий продавець заслуговує на інструменти, які справді працюють, не ставлячи під загрозу його дохід. Ми незалежні, запекло захищаємо нашу спільноту і створені продавцем для продавців.",
  "notice.ariaLabel": "Повідомлення про товарні знаки та авторські права",
