  "upgrade.doneUpgradeNow": "Business починається зараз за $29.99/місяць. Різниця в ціні потрапить до вашого наступного рахунку — без негайного стягнення.",
  "upgrade.doneDowngradeBody": "Ви зберігаєте Business до {date}, потім Essentials починається за $14.99/місяць. Повернення коштів за пониження немає.",
