  "upgrade.reviewJoin2": " і нашу",
  "upgrade.reviewPeriod": ".",
  "upgrade.upgradeNeverRestartsTrial": "Оновлення ніколи не перезапускає ваш безкоштовний пробний період.",
  "upgrade.trialHistoryNote": "Якщо ви платите за Essentials і переходите на Business, ви зберігаєте той самий обліковий запис клієнта та історію пробних періодів. Business не включає додатковий семиденний пробний період. Якщо ви оновлюєте, поки ваш початковий пробний період ще триває, його початкова дата завершення не скидається.",
  "upgrade.providerConfirmNote": "Зміни плану потребують підтвердження від постачальника платежів. Будь-яку різницю в ціні, перерахунок і дату набрання чинності має бути показано, перш ніж ви схвалите зміну. Оновлення не повинно створювати другу одночасну підписку.",
  "upgrade.chargedThroughProviderNote": "Зміни плану стягуються через постачальника платежів. Ви можете скасувати підписку з цієї сторінки за допомогою кнопки «Скасувати підписку» під вашим поточним планом або в налаштуваннях. Скасування зупиняє майбутні поновлення наприкінці вашого оплаченого періоду; воно ніколи не завершує ваш доступ одразу. Наявні безкоштовні робочі простори не стягуються за перегляд цих параметрів.",
  "billing.cancel.title": "Скасувати підписку",
  "billing.cancel.description": "Скасувати підписку на {plan}. Скасування зупиняє майбутні поновлення наприкінці вашого оплаченого періоду — воно ніколи не завершує ваш доступ одразу.",
  "billing.cancel.yourPlan": "ваш план",
  "billing.cancel.doneTitle": "Вашу підписку скасовано.",
  "billing.cancel.doneWithEnd": "Ви зберігаєте повний доступ до {endDate}. Після цієї дати у вас є пільговий період лише для читання тривалістю {graceDays} днів — ви все ще можете входити й бачити свої товари, але не можете нічого додавати, редагувати, видаляти, сканувати, імпортувати, експортувати чи змінювати. {gracePart}",
  "billing.cancel.graceEndsOn": "Після того, як 15-денний пільговий період завершиться {date}, ваш обліковий запис і всю його інформацію буде назавжди видалено без можливості відновлення.",
  "billing.cancel.doneNoEnd": "Ви зберігаєте повний доступ до кінця вашого оплаченого періоду. Після цього застосовується 15-денний пільговий період лише для читання. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Ви скасували протягом 3 днів після вашого першого оплаченого стягнення, тож ви можете мати право на повернення цього першого платежу. Скасування саме по собі не здійснює повернення — запросіть його через {contact}.",
  "billing.cancel.refundWindowClosed": "Скасування саме по собі не здійснює повернення. Повернення застосовується лише протягом 3 днів після першого успішного оплаченого стягнення, за запитом через {contact}.",
  "billing.cancel.notCanceledTitle": "Вашу підписку НЕ було скасовано.",
