  "billing.readiness.ready": "Оплата Stripe готова — ключі, підтвердження вебгуків і атестації підтверджено.",
  "billing.readiness.complimentaryProtected": "Ваш безкоштовний робочий простір Business захищено. Він не повинен ставати платним тестовим обліковим записом Essentials.",
  "billing.readiness.environmentIncomplete": "Не вдалося підтвердити всі облікові дані оплати Stripe, підтвердження вебгуків або зворотну адресу застосунку. Жодна оплата не може розпочатися.",
  "billing.readiness.ownerHasHistory": "Цей власник має попередні докази підписки або пробного періоду. Другу оплату не можна створювати.",
  "billing.readiness.trialAlreadyUsed": "Ознайомчий пробний період уже було використано або зарезервовано. Повторний пробний період не може розпочатися.",
  "billing.readiness.trialEligibilityUnverified": "Право на одноразовий пробний період не підтверджено для цього власника. Оплата залишається заблокованою.",
  "billing.readiness.testModeUnverified": "Записи облікового запису можна читати, але безпечне стримування тестового режиму Stripe та виконання платного поновлення не підтверджено. Оплата залишається заблокованою.",
  "billing.readiness.entitlementNotUnique": "Інформація про наявний план відсутня або неоднозначна. Жодна оплата не може розпочатися.",
  "billing.readiness.accountBillingIncomplete": "Історію платежів облікового запису не вдалося прочитати повністю. Жодна оплата не може розпочатися.",
  "billing.readiness.billingHistoryIncomplete": "Повну історію власника не вдалося підтвердити. Жодна оплата не може розпочатися.",
  "billing.readiness.ownershipMismatch": "Власність облікового запису або платіжні записи потребують перевірки, перш ніж будь-яку підписку можна буде розпочати.",
  "billing.readiness.catalogUnverified": "Затверджене серверне визначення оплати за $14.99/місяць потребує підтвердження.",
  "billing.readiness.auditUnavailable": "Перевірка сервера лише для читання була недоступна. Жодного платежу чи зміни облікового запису не відбулося.",
  "billing.dryRun.ariaLabel": "Симуляція тестового оновлення",
  "billing.dryRun.title": "Essentials → Business — тренувальна симуляція",
  "billing.dryRun.body": "Відпрацюйте запропоновані правила оновлення, використовуючи повністю вигадані записи в цьому браузері. Це не читає й не змінює ваш справжній TEST — зразок Pajama Pants, ваш поточний робочий простір Business, Stripe, пробні періоди, підписки чи запаси.",
  "billing.dryRun.runButton": "Запустити локальну симуляцію оновлення (без стягнення)",
