  "settings.deletion.submitError": "Не вдалося надіслати ваш запит. Спробуйте ще раз.",
  "settings.details.address": "Адреса",
  'settings.details.taxRate': 'Моя ставка податку',
  'settings.details.taxRateHint': 'Задайте один раз. Кожне нове замовлення на продаж саме заповнює свій податок за цією ставкою — податок окремого замовлення все одно можна змінити.',
  "settings.details.taxMode": "Як замовлення отримують свій податок",
  "settings.details.taxModeFixed": "Моя фіксована ставка",
  "settings.details.taxModeAutomatic": "Автоматично — за штатом клієнта",
  "settings.details.taxModeHint": "Фіксований режим застосовує вашу ставку до кожного нового замовлення. Автоматичний режим заповнює податок нового замовлення за базовою ставкою штату клієнта, щойно штат вказано в замовленні, і заповнює заново, якщо штат змінюється. Це базові ставки штатів — місцеві податки можуть додаватися. Замовлення без штату або з-за меж США використовує вашу фіксовану ставку вище.",
  'settings.details.gs1Prefix': "Префікс компанії GS1",
  'settings.details.gs1PrefixHint': "Лише якщо у вас є ліцензія на префікс GS1. Вкажіть його один раз, і генератор кодів у картці товару зможе створювати справжні роздрібні коди UPC та EAN із ваших власних номерів — кожен використовується один раз і ніколи повторно. Залиште порожнім, якщо префікса немає; застосунок ніколи не вигадує префікс.",
  'settings.details.gs1LearnMore': "Уперше маєте справу з GS1? Якщо ви живете у своїй країні, скористайтеся її посиланням, щоб дізнатися більше; якщо ви живете у Сполучених Штатах, скористайтеся посиланням GS1 US.",
