  "settings.pastDue.body": "Ваш останній платіж не пройшов. Ви зберігаєте повний доступ протягом 14 днів із моменту невдалого платежу, поки виправляєте його. Якщо платіж не буде виправлено, підписку буде скасовано, робочий простір стане доступним лише для перегляду на 15 днів, а потім обліковий запис і всю його інформацію буде видалено. Оплата в будь-який момент до видалення відновлює все. Якщо ви не знаєте, що робити, зверніться до підтримки за адресою theluminousbookshop@outlook.com.",
