  "workforce.unscheduledNote": "На сьогодні зміну не заплановано, тож цей час буде позначено як поза графіком.",
  "workforce.inbox.help": "Події табелю, відповіді щодо відсутностей, завдання, розрахункові листки й зміни графіка вашої команди — спочатку найновіші.",
  "workforce.messages.back": "Усі розмови",
