  "workforce.messages.emptyThread": "Повідомлень ще немає. Привітайтеся, щоб почати.",
  "workforce.messages.help": "Приватні повідомлення один на один із вашою командою — жоден інший застосунок не потрібен. Читати розмову можуть лише двоє її учасників, а також власник бізнесу, який наглядає за своїм магазином.",
  "workforce.messages.new": "Нове повідомлення",
