  "training.module.returns": "Повернення",
  "training.module.scanner": "Сканер",
  "training.module.settings": "Налаштування",
  "training.module.staff": "Персонал і ролі",
  "training.module.training": "Навчання",
  "training.module.workforce": "Команда й табель часу",
  "training.newForYou": "Нове навчання для вас",
  "training.newForYouHelp": "Ці уроки додано, бо ваша роль зросла або хтось призначив їх вам. Завершіть їх, щоб вивчити нові частини застосунку.",
