  "training.warningSentOn": "Попередження надіслано {date}",
  "auth.sameEmailNotice": "Уже маєте наш застосунок із Google Play або App Store? Використовуйте тут ту саму електронну пошту — ту, за якою ви входите в застосунок, — щоб ваш магазин і ваші запаси перейшли разом із вами. Інша електронна пошта починає цілком нову, порожню вітрину.",
  "settings.deleteConfirmWord": "ВИДАЛИТИ",
