  "recovery.title": "Відновити обліковий запис",
  "recovery.subtitle": "Втратили доступ до електронної пошти, під якою ваш обліковий запис? Ваші запасні ключі можуть повернути вас до вашого магазину.",
  "recovery.remembered": "Зрештою згадали?",
  "recovery.backToLogin": "Назад до входу",
