  "print.shippingNote": "Якщо в замовленні є адреса доставки, вона підставиться із замовлення. Те, що ви впишете тут, надрукується один раз і ніколи не збережеться.",
  "print.carrier.title": "Етикетка вашого перевізника",
  "print.carrier.desc": "Купуйте поштову відправку в перевізника, як ви робите сьогодні, — цей застосунок ніколи не продає поштові послуги, тож ціна, яку ви платите, завжди є ціною самого перевізника. Збережіть файл етикетки тут, і він назавжди залишиться на цьому замовленні: ваш запис, під рукою про всяк випадок.",
