  "print.carrier.pdfHint": "Ця етикетка — PDF. Вона відкривається у своєму справжньому розмірі — друкуйте з переглядача, і вона вийде рівно 4×6.",
  "print.carrier.pickOrderFirst": "Виберіть замовлення вище, а потім збережіть тут його етикетку перевізника.",
  'print.carrier.pickFirstTap': "Спочатку виберіть замовлення вище — потім ця кнопка збереже етикетку перевізника в цьому замовленні.",
  "print.style.title": "Стиль документів",
  "print.style.desc": "Зробіть ваші документи вашими. Ці налаштування вдягають ваш рахунок, чек, пакувальний лист, документи повернення, аркуші товарів, аркуші підрахунку та списки відбору — і запам’ятовуються для вашого бізнесу.",
  "print.style.logoLabel": "Ваш логотип",
