  "print.style.logoOff": "Логотипа ще немає. Додайте його в Налаштуваннях, і він друкуватиметься вгорі ваших документів.",
  "print.style.color": "Друк у кольорі",
  "print.style.colorHint": "Увімк: ваш логотип, картинки та рамка друкуються в кольорі. Вимк: усе друкується в чистому чорно-білому вигляді, заощаджуючи чорнило.",
  "print.style.font": "Шрифт документа",
