  "profile.title": "Ваша фотографія профілю",
  "profile.ownerDesc": "Ваша фотографія та ім'я, під яким вас знає ваша команда. Ваша власна фотографія відображається одразу — схвалення не потрібне.",
  "profile.memberDesc": "Ваша фотографія відображається поруч з вашим іменем після того, як власник її схвалить. До цього відображаються лише ваші ініціали.",
