  "apiErrors.profileOwnerNameTooLong": "Ім'я має містити не більше 80 символів.",
  "training.lessons.your-profile-photo.title": "Ваша фотографія профілю",
  "training.lessons.your-profile-photo.step1": "Ваша фотографія з'являється поруч з вашим іменем у верхній частині застосунку, на сторінці Персонал та поруч з вашими повідомленнями — після того, як власник її схвалить. До цього відображаються лише ваші ініціали.",
  "training.lessons.your-profile-photo.step2": "Відкрийте Налаштування та знайдіть Ваша фотографія профілю. Виберіть свою фотографію та надішліть її. Вона надсилається власнику на схвалення — вона ніде не з'являється, поки очікує.",
  "training.lessons.your-profile-photo.step3": "Коли власник її схвалить, ваш дзвіночок задзвенить і ваша фотографія почне відображатися. Якщо її не схвалено, виберіть іншу фотографію та надішліть її замість неї.",
  "training.lessons.your-profile-photo.step4": "Зміна фотографії працює так само: нова очікує на схвалення, а ваша поточна фотографія залишається на місці, доки нову не буде схвалено. Якщо зміну не схвалено, ви зберігаєте іншу фотографію.",
  "training.lessons.owner-profile-photos.title": "Фотографії профілю та ваше ім'я",
  "training.lessons.owner-profile-photos.step1": "Фотографія кожної людини відображається поруч з її іменем у верхній частині застосунку, на вашій сторінці Персонал та поруч з її повідомленнями. Фотографія учасника команди ніде не з'являється, доки ви її не схвалите — схвалення належить лише вам, і ніхто не може схвалити власну фотографію.",
  "training.lessons.owner-profile-photos.step2": "Коли хтось надсилає фотографію, ваш дзвіночок дзвенить. Відкрийте сторінку Персонал, щоб побачити її, потім виберіть Схвалити або Не схвалювати. Якщо ви її не схвалите, людині повідомлять, що потрібно вибрати іншу фотографію.",
  "training.lessons.owner-profile-photos.step3": "Якщо людина змінює свою фотографію, нова очікує на ваше схвалення так само. Її поточна фотографія залишається на місці, поки очікує — і залишається, якщо ви не схвалите зміну.",
  "training.lessons.owner-profile-photos.step4": "Ваша власна фотографія не потребує схвалення: встановіть її в Налаштуваннях, у розділі Ваша фотографія профілю. На тій самій картці знаходиться ваше ім'я — ім'я, яке ви там встановите, замінює слово Власник скрізь, де його бачить ваша команда, у застосунку та в Повідомленнях.",
  "payroll.dd.corrected": "Виправлена форма",
