  "training.lessons.owner-dd-setup.step5": "Надходить запечатана підписана форма: з рядка людини в розділі «Зарплата» ви можете відкрити її, щоб прочитати повні номери, роздрукувати або зберегти копію — редагувати її не можна ніколи. Якщо номер виглядає невірно, поверніть форму: людина виправить її та підпише заново сама, її виправлена форма замінить стару, а попередня залишиться в записі з датою заміни.",
