  "staffLib.area.clockAccess": "Табель і виклики",
  "staff.memberDialog.clockAccessHint": "Лише для менеджерів — дві окремі позначки. «Табель команди та пропущені виходи» дає цьому менеджеру бачити записи часу команди й виправляти записи часу на сторінці «Співробітники». «Виклики» дає цьому менеджеру відкривати вікна виклику, давати людині працювати, коли в неї немає зміни. Для звичайних співробітників ці позначки нічого не дають.",
