  "apiErrors.notFound.timeEntryFound": "Запис часу не знайдено.",
  "training.lessons.mgr-clock-callin.title": "Виклики та виправлення часу",
  "training.lessons.mgr-clock-callin.step1": "Власник може дати менеджеру дві окремі позначки. «Виклики» дозволяють відкрити вікно виклику для співробітника, а «Табель команди та пропущені виходи» дозволяє бачити табель команди й виправляти записи часу на сторінці «Співробітники». Кожна позначка працює сама по собі — менеджер може мати одну без іншої.",
  "training.lessons.mgr-clock-callin.step2": "Вікно виклику дозволяє людині увійти й відмітитися, коли жодна зміна її не покриває. Відкрийте його на сторінці «Співробітники», на картці «Виклики та пропущені виходи».",
  "training.lessons.mgr-clock-callin.step3": "Вікно лишається відкритим, доки ця людина не відмітить вихід, — після цього діє звичайний 10-хвилинний пільговий період перед виходом — або доки ви чи власник не закриєте його раніше. Саме воно не закривається.",
  "training.lessons.mgr-clock-callin.step4": "Коли хтось забуває відмітити вихід, його запис позначається на сторінці «Співробітники» та в розрахунку зарплати, щойно запланована зміна закінчується, а ви та власник отримуєте сповіщення. Запис продовжує рахуватися, доки його не виправлять.",
  "training.lessons.mgr-clock-callin.step5": "Виправте запис на сторінці «Співробітники»: вкажіть вхід, вихід і час перерв. Менеджер виправляє лише записи співробітників — записи менеджера виправляє власник.",
  "staffLib.perm.staffDocuments": "Документи персоналу",
  "staffLib.area.documentsAccess": "Документи персоналу",
  "staff.memberDialog.documentsAccessHint": "Лише для менеджерів — із цією позначкою менеджер може відкривати папки документів працівників: папери, що зберігаються на кожну людину, як-от форми W-4, заяви про прийом на роботу та копії посвідчень особи. Спершу знадобиться підтвердження — у цих папках є номери соціального страхування та дати народження. Для звичайних працівників ця позначка нічого не робить.",
  "staff.documentsWarning.body": "Ця людина зможе бачити конфіденційну інформацію про ваших працівників, зокрема номери соціального страхування та дати народження.",
