  "nav.xstoreMessages": "Повідомлення між магазинами",
  "plansLib.businessIncludes.xstoreMessages": "Повідомлення між магазинами — уся ваша команда, в усіх ваших компаніях",
  "xstore.title": "Повідомлення між магазинами",
  "xstore.help": "Усі люди в цьому обліковому записі, з усіх ваших компаній, в одній скриньці вхідних повідомлень. Пишіть будь-кому з них тут — текстом або голосом, із позначками про доставку та прочитання. Ваші Повідомлення всередині магазину залишаються як є.",
  "xstore.empty": "Розмов поки немає. Почніть одну за допомогою «Нове повідомлення».",
  "xstore.noPeople": "Поки більше немає кому писати. Люди з’являються тут, щойно приєднуються до однієї з ваших компаній і входять у систему.",
  "xstore.deliveredLabel": "Доставлено",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Повідомлення між магазинами входять до плану Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Ця людина не належить до цього облікового запису.",
  "training.lessons.owner-xstore-messages.title": "Повідомлення між вашими магазинами, для власників",
  "training.lessons.owner-xstore-messages.step1": "Повідомлення між магазинами — це друга скринька вхідних повідомлень, окрема від Повідомлень. Повідомлення призначені для магазину, у якому ви перебуваєте; ці двері відкривають доступ до всіх людей у вашому обліковому записі, у кожній компанії, якою ви володієте, — до п’яти.",
  "training.lessons.owner-xstore-messages.step2": "Відкрийте «Повідомлення між магазинами» в меню та почніть розмову з будь-якою людиною зі списку. У списку відображається кожен член команди з усіх ваших компаній, який увійшов у систему, разом із магазинами, у яких він працює.",
  "training.lessons.owner-xstore-messages.step3": "Фотографії йдуть разом: кожна людина показує свою схвалену фотографію профілю або свої ініціали, якщо фотографії немає. Кожне повідомлення містить дату й час його надсилання.",
  "training.lessons.owner-xstore-messages.step4": "Під своїми повідомленнями ви можете бачити «Доставлено», щойно повідомлення надходить, і «Прочитано», щойно інша людина відкриває розмову. Голосові повідомлення тут теж працюють, точно так само, як у Повідомленнях.",
  "training.lessons.owner-xstore-messages.step5": "Розмови тут є приватними для двох людей, які беруть у них участь. Ваш нагляд за Повідомленнями всередині магазину не поширюється на інші магазини.",
  "training.lessons.mgr-xstore-messages.title": "Повідомлення між вашими магазинами, для менеджерів",
  "training.lessons.mgr-xstore-messages.step1": "Повідомлення між магазинами охоплюють усіх людей у цьому обліковому записі, в усіх компаніях — а не лише магазин, у якому ви перебуваєте. Вони містяться в меню, окремо від Повідомлень.",
  "training.lessons.mgr-xstore-messages.step2": "Почніть розмову зі списку: там є кожен член команди, який увійшов у систему, а поруч із його ім’ям — магазини, у яких він працює.",
  "training.lessons.mgr-xstore-messages.step3": "Надішліть текст або запишіть голосове повідомлення. Перед надсиланням голосового повідомлення ви можете прослухати його, видалити або надіслати — так само, як у Повідомленнях.",
  "training.lessons.mgr-xstore-messages.step4": "Ваші повідомлення показують «Доставлено», коли вони надходять, і «Прочитано», коли інша людина відкриває розмову. Фотографія поруч із кожним ім’ям — це схвалена фотографія профілю цієї людини.",
  "training.lessons.staff-xstore-messages.title": "Повідомлення між вашими магазинами",
  "training.lessons.staff-xstore-messages.step1": "Повідомлення між магазинами — це місце, де ви можете зв’язатися з будь-якою людиною в цьому обліковому записі, у будь-якій компанії власника — запитанню для іншого магазину більше не потрібно чекати.",
  "training.lessons.staff-xstore-messages.step2": "Відкрийте їх у меню, виберіть людину та напишіть. Якщо потрібної вам людини немає у списку, вона ще не увійшла в систему — вона з’явиться, щойно увійде.",
  "training.lessons.staff-xstore-messages.step3": "Тут ви також можете надсилати голосові повідомлення: запишіть, прослухайте, а потім надішліть або видаліть. Кожне повідомлення показує дату й час його надсилання.",
  "training.lessons.staff-xstore-messages.step4": "Коли ви надсилаєте повідомлення, воно показує «Доставлено», щойно надходить, і «Прочитано», щойно інша людина відкриває розмову. Розмова є приватною для вас та іншої людини.",
