  "plansLib.businessIncludes.restaurantOps": "Операції ресторану — рахунки постачальників із тристоронньою звіркою, журнал відходів, терміни придатності та таблиця алергенів",
  "plansLib.businessIncludes.restaurantDaily": "Щоденні інструменти ресторану — журнали температури, дошка відсутніх страв, аркуші підготовки, інженерія меню, відхилення та експорт для бухгалтерії",
  "plansLib.businessIncludes.restaurantKitchen": "Ресторан, кухня та рецепти — рецепти з автоматичним списанням інгредієнтів та справжньою собівартістю страв, листи підготовки, серійне виробництво та інженерія меню",
  "plansLib.businessIncludes.restaurantStock": "Ресторан, склад і замовлення — рівні запасу (пар), посібник із замовлень постачальникам і переміщення між точками",
  "plansLib.businessIncludes.restaurantMoney": "Ресторан, рахунки та гроші — рахунки постачальників із тристоронньою звіркою, сповіщення про ціни, розбіжності та експорт у бухгалтерію",
  "plansLib.businessIncludes.restaurantSafety": "Ресторан, безпека їжі — журнали температур, терміни придатності в порядку «раніше спливає — раніше використати», етикетки з датами та таблиця алергенів",
