  "storefronts.connectedAs": "Підключено як {account}",
  "storefronts.disconnect": "Відключити",
  "storefronts.disconnectNote": "Відключення зупиняє надходження нових продажів. Уже записані продажі залишаються у вашій історії.",
  "storefronts.ebayDesc": "Підключіть свою вітрину eBay один раз. Коли товар продається на eBay, його кількість тут зменшується сама, а продаж записується у ваші рухи — так само, якби його відсканували на вибуття. Продажі йдуть лише в один бік: з eBay у застосунок.",
