  "storefronts.matchingIntro": "{count} проданих товарів ще не вдалося зіставити з продуктом. Пов'яжіть кожен із його продуктом, і його утримані продажі запишуться самі — поки він чекає, нічого не губиться.",
  "storefronts.matchingTitle": "Продажі, яким потрібне зіставлення",
